# This file was generated by AI

import math
from collections.abc import Callable, Mapping, Sequence


def validate_tsp_tour(
    route: Sequence[int] | None,
    city_coordinates: Mapping[int, Sequence[float]],
    distance_matrix: Sequence[Sequence[int | float]] | None = None,
    reported_length: float | None = None,
) -> tuple[bool, list[str]]:
    """
    Validate a TSP permutation route and optionally verify its tour length.
    """
    errors: list[str] = []

    if route is None:
        return False, ["Route is None"]

    expected_cities = set(city_coordinates.keys())
    n_cities = len(expected_cities)

    if len(route) != n_cities:
        errors.append(f"Expected {n_cities} cities in route, got {len(route)}")

    if len(route) > 0 and route[0] != 1:
        errors.append(f"Route must start at city 1, got {route[0]}")

    route_set = set(route)
    if route_set != expected_cities:
        missing = expected_cities - route_set
        extra = route_set - expected_cities
        if missing:
            errors.append(f"Missing cities in route: {sorted(missing)[:5]}")
        if extra:
            errors.append(f"Unexpected city IDs in route: {sorted(extra)[:5]}")

    if not errors and distance_matrix is not None and reported_length is not None:
        recomputed = 0
        for idx in range(n_cities):
            c1 = route[idx]
            c2 = route[(idx + 1) % n_cities]
            recomputed += distance_matrix[c1 - 1][c2 - 1]
        if not math.isclose(recomputed, reported_length, rel_tol=1e-9, abs_tol=1e-9):
            errors.append(
                f"Reported tour length {reported_length} does not match recomputed {recomputed}"
            )

    return len(errors) == 0, errors


def validate_continuous_vector(
    vector: Sequence[float] | None,
    dimension: int,
    lower: float,
    upper: float,
    func: Callable[[Sequence[float]], float] | None = None,
    reported_value: float | None = None,
    tol: float = 1e-12,
) -> tuple[bool, list[str]]:
    """
    Validate a continuous optimization solution vector against dimension and bounds.
    """
    errors: list[str] = []

    if vector is None:
        return False, ["Solution vector is None"]

    if len(vector) != dimension:
        errors.append(f"Expected dimension {dimension}, got {len(vector)}")

    for idx, val in enumerate(vector):
        if not math.isfinite(val):
            errors.append(f"Non-finite coordinate at index {idx}: {val}")
            break
        if val < lower - tol or val > upper + tol:
            errors.append(
                f"Coordinate {idx}={val} out of bounds [{lower}, {upper}]"
            )
            break

    if reported_value is not None and not math.isfinite(reported_value):
        errors.append(f"Non-finite reported objective value: {reported_value}")

    if (
        not errors
        and func is not None
        and reported_value is not None
        and math.isfinite(reported_value)
    ):
        recomputed = func(vector)
        if not math.isclose(recomputed, reported_value, rel_tol=1e-9, abs_tol=1e-9):
            errors.append(
                f"Reported value {reported_value} does not match recomputed {recomputed}"
            )

    return len(errors) == 0, errors
